</style>';}
 static function field(string $name,string $label,mixed $value='',string $type='text',bool $required=true):string{return '<label>'.self::e($label).'<input type="'.self::e($type).'" name="'.self::e($name).'" value="'.($type==='password'?'':self::e($value)).'" '.($required?'required':'').'></label>';}
 static function token(string $action):string{return '<input type="hidden" name="_token" value="'.self::e(csrf_token()).'"><input type="hidden" name="action" value="'.self::e($action).'">';}
 static function select(string $name,string $label,array $options,string $current):string{$h='<label>'.self::e($label).'<select name="'.self::e($name).'">';foreach($options as$k=>$v)$h.='<option value="'.self::e($k).'" '.($current===(string)$k?'selected':'').'>'.self::e($v).'</option>';return $h.'</select></label>';}
 static function document(string $title,string $body):string{return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).'</title></head><body style="margin:0;background:#f4f7fc"><main class="fcp" style="max-width:1100px;margin:30px auto;padding:20px">'.self::styles().$body.'</main></body></html>';}
